from pathlib import Path
import sys,json
ROOT=Path(__file__).resolve().parents[3]
sys.path.insert(0,str(ROOT/'scripts/r1v3'))
from build_plush_controls import raised_button
OUT=Path(__file__).resolve().parent
raised_button(520,240,(255,231,84),(255,185,13),48).save(OUT/'start-button-gold.png')
options=[('01','晴空蓝','清爽明快 · 金色主按钮更醒目','#72C9ED','#BCEAF4','#255D7C'),('02','薄荷青','柔和耐看，更贴合盆栽伙伴','#9DD9CD','#DAEEE0','#316C65'),('03','奶油米','温暖柔软，突出毛绒玩具质感','#EDDCB9','#FFF3D8','#806443'),('04','雾蓝灰','克制干净，让角色和金色按钮更突出','#9FB4CD','#CBD8E5','#465D7C')]
base='../P2-P4/delivery/home'
css='''*{box-sizing:border-box}body{margin:0;background:#f4f3ef;font-family:"PingFang SC",sans-serif;color:#253642;padding:36px}h1{font-size:28px;margin:0 0 8px}header p{margin:0;color:#6b767d;font-size:15px}main{display:flex;gap:22px;margin-top:28px}.option{width:324px}.caption{height:74px}.caption h2{font-size:20px;margin:0 0 8px}.caption p{font-size:12px;margin:0;color:#67777d}.phone{width:324px;height:576px;border-radius:22px;overflow:hidden;box-shadow:0 8px 22px #34425218;position:relative}.scene{width:540px;height:960px;position:relative;transform:scale(.6);transform-origin:top left;background:radial-gradient(ellipse at 50% 42%,#ffffff28,transparent 70%),linear-gradient(var(--top),var(--bottom))}.title{position:absolute;top:121px;width:100%;text-align:center;font-size:62px;font-weight:1000;letter-spacing:-3px;color:#fff8e8;-webkit-text-stroke:7px var(--ink);paint-order:stroke fill}.subtitle{position:absolute;top:207px;text-align:center;width:100%;font-size:22px;font-weight:700;color:var(--ink)}.member{position:absolute}.shadow{position:absolute;border-radius:50%;background:#24425822;filter:blur(5px)}.corner{position:absolute;width:64px;text-align:center;color:var(--ink);font-weight:800;font-size:20px}.corner img{width:60px;display:block;margin:auto}.codex{width:80px;font-size:23px}.codex img{width:80px}.start{position:absolute;left:140px;top:720px;width:260px;height:120px;background:url(start-button-gold.png) center/100% 100%;text-align:center;color:white;text-shadow:0 2px 1px #95500f}.main-label{font-size:35px;font-weight:900;-webkit-text-stroke:3.5px #985719;paint-order:stroke fill;line-height:48px;margin-top:13px}.level{display:table;margin:2px auto 0;padding:0 24px;background:#D99113;border-radius:20px;box-shadow:inset 0 1px 2px #a7681230;font-size:22px;line-height:29px;font-weight:800;-webkit-text-stroke:2px #985719;paint-order:stroke fill}.next{position:absolute;top:866px;left:0;width:100%;text-align:center;font-size:18px;font-weight:600;color:var(--ink)}.palette{display:flex;align-items:center;gap:8px;margin-top:16px;color:#66747b;font-size:12px}.swatch{width:16px;height:16px;border-radius:50%;display:inline-block}footer{margin-top:24px;font-size:13px;color:#6b767d}'''
html='<!doctype html><meta charset="utf-8"><title>泡泡小队 · 主页背景四版</title><style>'+css+'</style><header><h1>泡泡小队 / 主页背景四版</h1><p>角色向中间收拢 · 图鉴移至右下并放大 · 关卡文字增加深金色底板</p></header><main>'
for n,name,desc,top,bottom,ink in options:
 html+=f'<section class="option"><div class="caption"><h2>{n}　{name}</h2><p>{desc}</p></div><div class="phone"><div class="scene" style="--top:{top};--bottom:{bottom};--ink:{ink}"><div class="title">泡泡小队</div><div class="subtitle">毛绒伙伴 · 一起出发</div>'
 for color,x,foot,h in [('orange',193,441,200),('yellow',347,441,194),('green',163,610,204),('purple',377,610,204),('blue',270,665,267)]:
  w=h*.875;y=foot-h*212/256
  html+=f'<div class="shadow" style="left:{x-w*.375}px;top:{foot-7}px;width:{w*.75}px;height:17px"></div><img class="member" src="{base}/{color}/idle.png" style="left:{x-w/2}px;top:{y}px;width:{w}px;height:{h}px">'
 html+=f'<div class="corner" style="left:20px;top:45px"><img src="{base}/btn-settings.png">设置</div><div class="corner codex" style="right:15px;top:733px"><img src="{base}/btn-codex.png">图鉴</div><div class="start"><div class="main-label">开始游戏</div><div class="level">第 1 关</div></div><div class="next">新伙伴 小蓝 · 通关这一关就来啦！</div></div></div><div class="palette"><i class="swatch" style="background:{top}"></i>{top}<span>→</span><i class="swatch" style="background:{bottom}"></i>{bottom}</div></section>'
html+='</main><footer>设计对比稿 V2，非游戏运行截图。下方布局参考图 1；金色按钮与关卡底板参考「暴走闯关者」。两侧保留功能按钮空间。</footer>'
(OUT/'preview.html').write_text(html)
(OUT/'palettes.json').write_text(json.dumps(options,ensure_ascii=False,indent=2))
